import * as React from 'react'
import { graphql, Link } from 'gatsby'
import { GatsbyImage, IGatsbyImageData } from 'gatsby-plugin-image'

import "../scss/main.scss"

import Header from "../components/Header"
import Footer from "../components/Footer"
import AccentDots from "../components/AccentDots"
import Seo from "../components/Seo"

interface GalleryGroup {
  fieldValue: string
  nodes: Array<{
    name: string
    childImageSharp: {
      gatsbyImageData: IGatsbyImageData
    }
  }>
}

interface PageProps {
  data: {
    allFile: {
      group: GalleryGroup[]
    }
  }
}

const PhotographyPage: React.FC<PageProps> = ({ data }) => {
  return (
    <div className="container">
      <Header />
      <div className="gallery-hero">
        <h1>Photography</h1>
        <p>Capturing the character, movement, and energy of birds in their element.</p>
        <AccentDots />
      </div>
      <div className="explore-bar">
        <Link to="/photo-journeys" className="explore-bar__pill"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M23 19a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h4l2-3h6l2 3h4a2 2 0 0 1 2 2z"/><circle cx="12" cy="13" r="4"/></svg> Photo Journeys</Link>
      </div>
      <div className="explore-bar--mobile">
        <Link to="/photo-journeys" className="explore-bar__pill"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M23 19a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h4l2-3h6l2 3h4a2 2 0 0 1 2 2z"/><circle cx="12" cy="13" r="4"/></svg> Photo Journeys</Link>
      </div>
      <div className="galleries-container">
        <div className="galleries-grid">
          {data.allFile.group
            .filter((gallery) => gallery.fieldValue !== 'new-year-26')
            .map((gallery) => {
            const galleryName = gallery.fieldValue
            const galleryTitle = galleryName
              .split('-')
              .map(word => word.charAt(0).toUpperCase() + word.slice(1))
              .join(' ')

            const coverCovers: Record<string, string> = {
              'birds-in-trees': 'photo54',
              'birds-by-water': 'photo2',
              'birds-in-flight': 'photo2',
            }
            const preferredCover = coverCovers[galleryName]
            const coverNode = preferredCover
              ? gallery.nodes.find(n => n.name === preferredCover)
              : undefined
            const fallbackIndex = Math.floor(gallery.nodes.length / 2)
            const coverImage = (coverNode || gallery.nodes[fallbackIndex])?.childImageSharp?.gatsbyImageData

            return (
              <Link
                key={galleryName}
                to={`/photography/${galleryName}`}
                className="gallery-card"
              >
                {coverImage && (
                  <GatsbyImage
                    image={coverImage}
                    alt={galleryTitle}
                    className="gallery-cover"
                  />
                )}
                <div className="gallery-info">
                  <h2>{galleryTitle}</h2>
                  <p>{gallery.nodes.length} photos</p>
                </div>
              </Link>
            )
          })}
        </div>
      </div>
      <Footer />
    </div>
  )
}

export const pageQuery = graphql`
  query PhotographyGalleriesQuery {
    allFile(
      filter: {
        sourceInstanceName: { eq: "photography" }
        relativeDirectory: { ne: "" }
      }
      sort: { relativeDirectory: ASC }
    ) {
      group(field: { relativeDirectory: SELECT }) {
        fieldValue
        nodes {
          name
          childImageSharp {
            gatsbyImageData(
              width: 800
              height: 800
              placeholder: BLURRED
              transformOptions: { fit: COVER, cropFocus: CENTER }
            )
          }
        }
      }
    }
  }
`

export const Head = () => <Seo title="Photography" description="Bird and nature photography." />

export default PhotographyPage
